/* ---------------------------------------------------------------------------------------------
   RUDIMENT CATALOG, INLINED (2026-08-05).

   This was its own rudiments-data.js. Keeping it separate meant adding a file to the app bundle's
   toolEmbed manifest, and the manifest ships INSIDE the React app — so the tool could not be updated
   without also redeploying the app. That breaks the property the vault exists for: tool code is
   uploaded on its own and every client picks it up on the next load.

   It bit for real: the vault got an embed.html carrying a Rudiments tab while the deployed app still
   had the old manifest, so window.RDM_RUDIMENTS was undefined and the tab rendered empty. Living here,
   inside a file the manifest already lists, the catalog travels with the generator and no app deploy
   is ever required.
   Regenerate with dev/sr-rudiments-test/build-rudiments-data.js, then paste the result back here.
   --------------------------------------------------------------------------------------------- */
